window.ARCADE={"modes": [{"id": "reflection", "icon": "◈", "title": "Reflective practice", "subtitle": "The cycle, Johns’s model and self-awareness.", "detail": "Examine intentions, assumptions and outcomes.", "interaction": "Multiple choice"}, {"id": "defences", "icon": "✳", "title": "Defence mechanisms", "subtitle": "Five mature responses and the distinctions that matter.", "detail": "Compare close scenarios and plausible alternatives.", "interaction": "Multiple choice"}, {"id": "care", "icon": "◇", "title": "Professional judgment", "subtitle": "Client choice, boundaries, privacy and safety.", "detail": "Apply reflective reasoning to care situations.", "interaction": "Multiple choice"}, {"id": "truefalse", "icon": "✓", "title": "True or false", "subtitle": "Test the claims that sound almost right.", "detail": "Read the rationale and correct each false statement.", "interaction": "True / false"}, {"id": "scenarios", "icon": "✎", "title": "Integrated scenarios", "subtitle": "Connect several concepts in demanding care situations.", "detail": "Choose the strongest complete response, then review the rationale.", "interaction": "Multiple choice"}], "topics": ["Critical reflection", "Reflective versus reflexive", "Self-reflection", "Outcomes", "Seven-step cycle", "Goals and plans", "Johns model", "Intentions and context", "Emotional needs", "Refusal and boundaries", "Self-awareness", "Objective documentation", "Confidentiality", "Mature defences", "Other defences", "Boundaries", "Accountability", "Feedback", "Models", "Scope and support", "Reflective practice", "Gender preference", "Refusal", "Person-centred planning", "Autonomy and scope", "Autonomy and risk", "Wound-care refusal", "Professional development", "Emotional regulation", "Documentation and scope", "Home-care boundaries", "Self-worth", "Reflexivity", "Strategies versus defences", "Home-visit safety", "Safety", "Source fidelity and safety", "Advocacy", "Care plan", "Privacy", "Reflective records", "Documentation", "Treatment preferences", "Communication between settings", "Treatment orders", "End-of-life scope", "Grief and reflection", "Suppression", "Anticipation", "Altruism", "Humour", "Sublimation", "Suppression and avoidance", "Mature distinctions", "Displacement correction", "Other mechanisms", "Self, Person, environment", "What Why How", "Value and needs", "Journaling", "Reflective habit", "Positive reflection", "Necessity and scope", "Cycle application", "Circular process", "Cycle first step", "Model distinction", "Depth versus checklist", "Johns aims and effects", "Johns background", "Reflexivity and position", "Non-verbal self-awareness", "Changing intentions", "Defences", "Reflection", "Cycle", "Preference", "Capacity", "Risk language", "Orders", "End of life", "Development", "Needs", "Integrated refusal", "Johns synthesis", "Cycle synthesis", "Defence comparison", "Confidentiality synthesis", "Gender preference synthesis", "Autonomy synthesis", "Wound-care synthesis", "Home safety synthesis", "Advocacy synthesis", "Orders synthesis", "End-of-life synthesis", "Documentation synthesis", "Mature responses synthesis", "Reflection and reflexivity synthesis"], "questions": [{"id": "ch6-001", "chapter": 6, "mode": "reflection", "topic": "Critical reflection", "difficulty": 2, "prompt": "An HCA repeatedly reviews a tense interaction and becomes more certain that the client was unreasonable. Which addition would most clearly turn this review into productive reflection?", "choices": ["Examine personal assumptions, compare intentions with effects, and plan a change to evaluate.", "Reconstruct the conversation until the HCA can prove the original approach was justified.", "Identify the client’s personality type to predict future refusals.", "Focus on feelings without considering subsequent actions."], "answer": 0, "explain": "Reflection examines the self and contributing factors and uses insight to guide future practice. Rehearsing blame, proving oneself right, or stopping at emotion does not complete that learning process.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-002", "chapter": 6, "mode": "reflection", "topic": "Reflective versus reflexive", "difficulty": 2, "prompt": "During care, an HCA notices that fear of criticism is making their tone abrupt. They slow down, clarify the client’s concern, and later examine the interaction in writing. Which interpretation is most accurate?", "choices": ["Changing tone during care makes later reflection unnecessary.", "Only the later writing is relevant to self-awareness.", "The HCA is reflecting the client’s feelings back, so this is exclusively therapeutic reflection.", "The in-the-moment examination illustrates reflexivity, complemented by later reflection."], "answer": 3, "explain": "The chapter highlights simultaneously examining oneself and interacting as an aspect of reflexivity. Later reflection can consolidate learning. Reflecting a client’s feelings back is a different communication process.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-003", "chapter": 6, "mode": "reflection", "topic": "Self-reflection", "difficulty": 2, "prompt": "An HCA says, “You seem disappointed that the visit ended early.” What additional activity would specifically demonstrate self-reflection?", "choices": ["Asking a colleague to repeat the statement.", "Observing whether the client nods.", "Repeating the statement in simpler language.", "Considering whether the HCA’s own discomfort with sadness led them to end the visit abruptly."], "answer": 3, "explain": "Reflecting perceived feelings back to a client differs from examining one’s own motives, reactions, and contribution.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-004", "chapter": 6, "mode": "reflection", "topic": "Critical reflection", "difficulty": 2, "prompt": "After an interaction, an HCA accurately lists everything said but concludes, “There is nothing else to examine because the facts are recorded.” What is the main limitation?", "choices": ["Reflection must exclude description to avoid repetition.", "Only unsuccessful interactions require analysis.", "A factual description must be replaced by emotional impressions.", "The account omits analysis of meaning, assumptions, contributing factors, and future responses."], "answer": 3, "explain": "Description is a foundation, not the whole reflective process. Analysis and resulting learning give the account practical value.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-005", "chapter": 6, "mode": "reflection", "topic": "Outcomes", "difficulty": 2, "prompt": "A client accepts assistance and the task is completed, but the HCA remembers interrupting them several times. Which reflective conclusion is strongest?", "choices": ["The interruptions invalidate every positive aspect of the encounter.", "Evaluate both the overall outcome and individual events; retain helpful actions while examining avoidable interruptions.", "Completion proves the interruptions were necessary.", "Only the client’s final words should influence future practice."], "answer": 1, "explain": "The chapter considers the overall result while also exploring details and reactions. A positive endpoint does not remove the need to examine potentially harmful communication.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-006", "chapter": 6, "mode": "reflection", "topic": "Seven-step cycle", "difficulty": 2, "prompt": "An HCA has described a recurring interaction, explored reactions and contributing factors, and identified a need to improve. What should follow before choosing specific strategies?", "choices": ["Establish a goal for future similar interactions.", "Repeat the description until no emotion remains.", "Apply the first available technique.", "Classify the client’s defence mechanism."], "answer": 0, "explain": "In the seven-step reflective sequence, analysis informs future goals; strategies and action plans follow those goals.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-007", "chapter": 6, "mode": "reflection", "topic": "Seven-step cycle", "difficulty": 2, "prompt": "Which sequence best represents the seven-step reflective cycle used in this course?", "choices": ["Allocate time; describe; diagnose others; choose a goal; suppress feelings; act; finish permanently.", "Describe; choose an experience; act; explore reactions; schedule time; plan; set goals.", "Allocate time; choose an experience; describe and explore it; examine reactions and results; establish goals; develop a plan; apply learning in practice.", "Choose an experience; set goals; allocate time; act; describe; plan; examine reactions."], "answer": 2, "explain": "This preserves the course sequence: time, experience, description, exploration of reactions/results, goals, plan, and implementation. Further experience feeds the cycle. Labels are paraphrased rather than presented as verbatim diagram text.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-008", "chapter": 6, "mode": "reflection", "topic": "Goals and plans", "difficulty": 2, "prompt": "“At my next three morning-care encounters, I will ask the client’s preferred order before beginning and review whether this improved participation.” Which distinction is most accurate?", "choices": ["Asking about order is a goal; improved participation is a description.", "Reviewing encounters replaces the need to apply the strategy.", "Improved participation is the intended outcome; asking about order is a strategy; reviewing encounters supports evaluation.", "The statement concerns only the client and therefore cannot be reflective."], "answer": 2, "explain": "The outcome sought, the action intended, and the later evaluation serve different functions. This makes learning actionable rather than merely aspirational.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-009", "chapter": 6, "mode": "reflection", "topic": "Johns model", "difficulty": 2, "prompt": "An HCA writes, “I could have paused, but I feared appearing incompetent. A pause might have allowed the client to explain.” Which Johns-model element is most directly developed?", "choices": ["Resultant learning only.", "Description of the experience.", "Alternative actions, why they were not chosen, and their possible consequences.", "Significant background information only."], "answer": 2, "explain": "This considers an alternative, the barrier to selecting it, and its likely consequences. Several elements can overlap, but this is the explicit focus.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-010", "chapter": 6, "mode": "reflection", "topic": "Johns model", "difficulty": 2, "prompt": "Which reflection most directly examines the aims of an action, rather than its consequences?", "choices": ["The client stopped speaking after I interrupted.", "The corridor was noisy and the client had slept poorly.", "I interrupted because I wanted to finish quickly and reassure myself that I was efficient.", "Next time I will allow a longer pause."], "answer": 2, "explain": "Aims concern what the worker was trying to achieve and reasons for acting. Silence is a consequence, noise is background, and a future pause is learning or planning.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-011", "chapter": 6, "mode": "reflection", "topic": "Johns model", "difficulty": 2, "prompt": "A written reflection includes events, possible causes, background, aims, consequences, and alternative actions. It ends without specifying what was learned. What is missing from Johns’s seven-part examination?", "choices": ["A diagnosis explaining the HCA’s reaction.", "An assurance that the same technique will work for everyone.", "Proof that the client’s emotions were irrational.", "Resultant learning and how future reactions may change."], "answer": 3, "explain": "Johns’s final element connects the examination to learning and future reactions. The model seeks depth, not completion of a checklist alone.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-012", "chapter": 6, "mode": "reflection", "topic": "Intentions and context", "difficulty": 2, "prompt": "A daughter initially offers to care for her mother at home. Shortly before a planning meeting, she discovers an unexpected care need and becomes hesitant. What is the strongest initial interpretation?", "choices": ["Her siblings should decide before she becomes more emotional.", "The new event may have changed her feelings, expectations, or perceived ability to help; clarify these rather than assuming motives.", "Her earlier offer was dishonest.", "Her hesitation demonstrates that home care is unsuitable."], "answer": 1, "explain": "The chapter’s family-meeting example highlights how an unexpected event can alter emotions and intentions. The explanation remains a hypothesis to explore, not an established motive or placement decision.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-013", "chapter": 6, "mode": "care", "topic": "Emotional needs", "difficulty": 2, "prompt": "An HCA becomes resentful when clients do not thank them. Which response best addresses the underlying professional-boundary concern?", "choices": ["Conclude that caring requires having no emotional needs.", "Recognize the need for appreciation, seek appropriate support outside client relationships, and examine its effect on care.", "Provide more help to clients who offer praise.", "Ask each client to acknowledge the HCA’s effort."], "answer": 1, "explain": "The chapter warns against centring care on fulfilment of the worker’s dominant personal needs. Needs can be acknowledged and supported without making clients responsible for meeting them.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-014", "chapter": 6, "mode": "care", "topic": "Refusal and boundaries", "difficulty": 2, "prompt": "A client declines non-urgent assistance with dressing and says, “I want to do it myself.” There is no immediate safety emergency. Which response best combines reflection and person-centred care?", "choices": ["Ask what support, if any, the client wants, consider suitable alternatives within the care plan, and report/document relevant facts under workplace procedures.", "Complete the task because efficiency protects everyone’s time.", "Leave without clarifying and assume all future assistance is refused.", "Tell the client that refusal proves they do not understand their needs."], "answer": 0, "explain": "Clarification supports choice without coercion. Relevant communication and documentation support continuity. This educational scenario does not establish a blanket legal rule or authorize independent changes outside the HCA’s role.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-015", "chapter": 6, "mode": "reflection", "topic": "Self-awareness", "difficulty": 2, "prompt": "Following that refusal, the HCA thinks, “They are rejecting me personally.” Which reflective question is most useful?", "choices": ["Which defence mechanism proves the client dislikes me?", "How can I persuade them to show respect?", "What evidence supports my interpretation, and how might my need to feel useful be shaping it?", "Which colleague is best at making this client comply?"], "answer": 2, "explain": "Separating observed refusal from personal interpretation reveals assumptions and emotional needs. A refusal of assistance does not establish rejection of the worker.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-016", "chapter": 6, "mode": "care", "topic": "Objective documentation", "difficulty": 2, "prompt": "At 08:20 a client says, “No shower now; I’m cold.” The HCA offers to return later, the client agrees, and the HCA informs the supervising nurse at 08:25. Which entry best distinguishes observation from judgment?", "choices": ["Client manipulative and noncompliant again; nurse aware.", "08:20: Client stated, “No shower now; I’m cold.” Offered to return later; client agreed. Supervising nurse informed at 08:25.", "Client refused hygiene because of an attention-seeking personality.", "Client would not cooperate but eventually became reasonable."], "answer": 1, "explain": "The entry uses a relevant quote, records the response and notification, and avoids inferred motives or character labels. Actual charting must also follow workplace requirements.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-017", "chapter": 6, "mode": "care", "topic": "Confidentiality", "difficulty": 2, "prompt": "An HCA wants to reflect with a colleague on a distressing interaction. Which approach best protects confidentiality while preserving learning?", "choices": ["Post an unnamed story online containing enough unique details to identify the client.", "Copy the full care record into a personal journal.", "Use an authorized private setting and share only information needed for the professional discussion, following policy.", "Discuss identifiable details in a public café because the purpose is educational."], "answer": 2, "explain": "Purpose alone does not make disclosure appropriate. A private authorized discussion and limited relevant detail support confidentiality. Removing a name may not sufficiently de-identify a distinctive story.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-018", "chapter": 6, "mode": "defences", "topic": "Mature defences", "difficulty": 2, "prompt": "After being criticized, an HCA recognizes an impulse to throw something. Later, they channel that aggressive energy into a vigorous game of squash. What mechanism is most specifically illustrated?", "choices": ["Projection.", "Displacement.", "Sublimation.", "Repression."], "answer": 2, "explain": "Sublimation channels an unacceptable impulse into a personally and socially acceptable activity. Displacement redirects emotion unhealthily toward another target.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-019", "chapter": 6, "mode": "defences", "topic": "Mature defences", "difficulty": 2, "prompt": "An HCA recognizes sadness during a busy shift, deliberately postpones processing it until a planned debrief, and attends that debrief. Which mechanism fits best?", "choices": ["Suppression.", "Denial.", "Reaction formation.", "Repression."], "answer": 0, "explain": "Suppression involves temporarily setting a thought or feeling aside and returning to it. Awareness and intentional postponement distinguish it from unconscious repression or refusal to accept reality.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-020", "chapter": 6, "mode": "defences", "topic": "Mature defences", "difficulty": 2, "prompt": "Before a potentially difficult family meeting, an HCA considers likely stressors and prepares appropriate ways to respond. What is the most specific mature mechanism?", "choices": ["Fantasy.", "Anticipation.", "Projection.", "Isolation of affect."], "answer": 1, "explain": "Anticipation involves preparing for expected future difficulty. It differs from withdrawing into an imaginary resolution or using detail to avoid feeling.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-021", "chapter": 6, "mode": "defences", "topic": "Mature defences", "difficulty": 2, "prompt": "An HCA copes with personal distress by participating in a suitable community volunteer activity, with concern for others and no expectation of praise. Which mature mechanism is most directly illustrated?", "choices": ["Displacement.", "Reaction formation.", "Denial.", "Altruism."], "answer": 3, "explain": "Altruism involves selfless concern for others. An emotional benefit to the helper does not by itself make the act approval-seeking. The scenario explicitly excludes an expectation of praise.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-022", "chapter": 6, "mode": "defences", "topic": "Mature defences", "difficulty": 2, "prompt": "Which use of humour best fits the chapter’s mature response?", "choices": ["Laughing about a client’s private difficulty with unrelated staff.", "Joking that a serious concern is imaginary.", "Making a joke that acknowledges a shared difficulty and eases tension without dismissing pain.", "Using sarcasm to stop a client from expressing fear."], "answer": 2, "explain": "Mature humour permits expression and reduces tension while recognizing seriousness. Dismissal, humiliation, and inappropriate disclosure are not justified by calling them humour.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-023", "chapter": 6, "mode": "defences", "topic": "Other defences", "difficulty": 2, "prompt": "After being reprimanded by a supervisor, a worker goes home and shouts at a roommate over a minor inconvenience. Which mechanism is most directly illustrated?", "choices": ["Suppression.", "Anticipation.", "Displacement.", "Sublimation."], "answer": 2, "explain": "The strong feelings are redirected unhealthily from the original person to another. The aggression has not been transformed into an acceptable outlet.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-024", "chapter": 6, "mode": "defences", "topic": "Other defences", "difficulty": 2, "prompt": "A worker is angry with a colleague but does not acknowledge it. Instead, the worker becomes convinced that the colleague is angry with them. What mechanism fits this pattern?", "choices": ["Displacement.", "Projection.", "Repression.", "Altruism."], "answer": 1, "explain": "Projection attributes one’s unacceptable feeling to another person. Displacement instead changes the target of the expressed feeling. These are teaching patterns, not diagnoses from a single observation.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-025", "chapter": 6, "mode": "defences", "topic": "Other defences", "difficulty": 2, "prompt": "Which feature most clearly distinguishes repression from suppression in this chapter?", "choices": ["Repression is an unconscious removal from awareness; suppression is a temporary decision to put something aside.", "Repression concerns future events; suppression concerns the past.", "Repression uses written reflection; suppression does not.", "Repression always involves directing anger at another person."], "answer": 0, "explain": "The defining distinction is awareness and temporary postponement versus unconscious exclusion. Directing anger toward another target describes displacement.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-026", "chapter": 6, "mode": "defences", "topic": "Other defences", "difficulty": 2, "prompt": "A person’s conscious feelings toward someone are the opposite of their underlying unconscious wishes. Which mechanism best matches that definition?", "choices": ["Reaction formation.", "Anticipation.", "Sublimation.", "Fantasy."], "answer": 0, "explain": "Reaction formation involves consciously experiencing the opposite of underlying unconscious wishes or emotions. Merely behaving politely while knowingly angry would not establish it.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-027", "chapter": 6, "mode": "defences", "topic": "Other defences", "difficulty": 2, "prompt": "During a painful personal event, a person focuses excessively on schedules, terminology, and technical detail to avoid experiencing emotion. Which response best fits the chapter’s terminology?", "choices": ["Humour.", "Projection.", "Altruism.", "Isolation of affect / intellectualisation."], "answer": 3, "explain": "The chapter groups isolation of affect with intellectualisation and describes using conscious detail to avoid uncomfortable emotion. Accurate practical planning alone would not establish this mechanism.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-028", "chapter": 6, "mode": "defences", "topic": "Other defences", "difficulty": 2, "prompt": "A person temporarily refuses to believe distressing news but later begins to acknowledge it. What conclusion is best supported?", "choices": ["Any denial establishes a psychiatric disorder.", "Denial can temporarily help functioning; persistence and consequences matter when considering its effects.", "Acknowledging reality later proves denial did not occur.", "Denial and suppression are interchangeable because both are deliberate."], "answer": 1, "explain": "The chapter describes short-term denial as potentially helpful in grief and warns about over-reliance. Its category labels are not sufficient grounds for diagnosing a person.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-029", "chapter": 6, "mode": "care", "topic": "Boundaries", "difficulty": 2, "prompt": "An HCA feels angry after being insulted. Which response best combines accountability with appropriate boundaries?", "choices": ["Assume that taking responsibility for a response makes the insult acceptable.", "Recognize the feeling, choose a safe response, set a respectful limit, and obtain appropriate help if safety requires it.", "Treat anger as proof of professional failure.", "Remain alone in an escalating situation to demonstrate self-control."], "answer": 1, "explain": "Self-awareness concerns managing one’s response, not accepting abuse or ignoring safety. The instructor’s example supports a respectful limit and appropriate support rather than retaliation.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-030", "chapter": 6, "mode": "care", "topic": "Accountability", "difficulty": 2, "prompt": "A colleague says, “Reflection means recognizing that clients cannot be harmed emotionally by how we speak.” Which correction is best?", "choices": ["A reflective worker can predict and control every client emotion.", "The client’s interpretation is irrelevant to reflection.", "Only intentions matter if the worker remains calm.", "Responsibility for managing our responses does not remove our duty to examine how our conduct affects others."], "answer": 3, "explain": "The course emphasis on personal emotional responsibility must not erase the impact of communication. Reflection examines both intentions and effects without claiming total control of another person’s feelings.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-031", "chapter": 6, "mode": "reflection", "topic": "Self-awareness", "difficulty": 2, "prompt": "An HCA notices feeling unusually impatient only when a client resembles someone from a past conflict. Which next step best reflects self-awareness?", "choices": ["Explore the association and its effect on interpretation, then plan how to keep care responsive to this client.", "Ask the client to avoid reminding the HCA of that person.", "Stop examining the reaction because its cause is outside work.", "Assume the client has the same intentions as the person from the past."], "answer": 0, "explain": "Past experience can shape present reactions. Recognizing that influence allows the HCA to question assumptions rather than transfer an old relationship onto the current client.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-032", "chapter": 6, "mode": "reflection", "topic": "Feedback", "difficulty": 2, "prompt": "A colleague offers feedback that conflicts with an HCA’s self-image. Which response most supports reflective learning?", "choices": ["Reject it unless the colleague has the same personality.", "Ask whether other staff like the HCA before discussing examples.", "Accept every interpretation as a proven fact.", "Compare specific examples with personal observations, examine defensiveness, and identify useful changes."], "answer": 3, "explain": "Feedback is information to examine honestly, not automatically accept or reject. Specific evidence supports learning about strengths and areas for improvement.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-033", "chapter": 6, "mode": "reflection", "topic": "Models", "difficulty": 2, "prompt": "Two HCAs use different reflective models and both identify justified changes that improve communication. What is the strongest conclusion?", "choices": ["Only one model can be legitimate.", "A model can be selected for fit with the individual’s thinking and learning needs while retaining depth and application.", "A model is useful only when it prevents uncomfortable feelings.", "Models remove the need to consider evidence and ethics."], "answer": 1, "explain": "The chapter supports selecting a suitable model. Its purpose is to guide thoughtful exploration, not replace judgment, evidence, or ethical consideration.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-034", "chapter": 6, "mode": "reflection", "topic": "Critical reflection", "difficulty": 2, "prompt": "A worker interprets a client’s limited eye contact as disrespect. What is the most critically reflective response?", "choices": ["Use the interpretation as an objective observation.", "Explore personal expectations and relevant context, and clarify meaning without assuming a cultural explanation.", "Assume limited eye contact always has the same cultural meaning.", "Avoid communication because clarification could be uncomfortable."], "answer": 1, "explain": "Critical self-awareness challenges the worker’s interpretation. Context and the individual’s perspective should be explored; a cultural stereotype would simply replace one unsupported assumption with another.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-035", "chapter": 6, "mode": "care", "topic": "Scope and support", "difficulty": 2, "prompt": "A worker’s reflection identifies a situation beyond their knowledge and role. What is the best next step?", "choices": ["Conclude that reflection has failed because outside help is needed.", "Tell the client the worker’s personal history to establish credibility.", "Invent a solution so the reflective cycle can be completed independently.", "Seek appropriate supervision or referral and use the learning to guide future communication within the role."], "answer": 3, "explain": "The chapter recognizes that no professional has every answer and that appropriate support or referral may be needed. Insight into limitations is a useful reflective outcome.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-036", "chapter": 6, "mode": "reflection", "topic": "Reflective practice", "difficulty": 2, "prompt": "Which evidence most strongly demonstrates reflective practice over time?", "choices": ["The worker can recite all model labels.", "The worker produces increasingly long descriptions.", "The worker identifies a recurring trigger, applies a justified change, and reviews its effects across later encounters.", "The worker never experiences discomfort again."], "answer": 2, "explain": "Reflective practice involves using learning to change or reinforce behaviour over time. Label recall and volume of writing do not establish application, and discomfort can still occur.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-037", "chapter": 6, "mode": "care", "topic": "Gender preference", "difficulty": 2, "prompt": "A client requests a female caregiver for intimate care. The assigned male HCA feels personally rejected. Which response best integrates self-awareness and client-centred care?", "choices": ["Promise that only female workers will attend from now on.", "Explain that a professional client should accept any assigned worker.", "Acknowledge the preference, notify the supervisor, and explore available options within staffing and policy.", "Record that the client discriminates against all male staff."], "answer": 2, "explain": "Acknowledge the stated preference without treating it as a judgment of personal worth. Staffing arrangements require appropriate coordination; the HCA should neither guarantee an unavailable option nor assign an unsupported motive.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-038", "chapter": 6, "mode": "care", "topic": "Refusal", "difficulty": 2, "prompt": "A client declines a shower. Which opening question most effectively tests the HCA’s assumption that the client is being difficult?", "choices": ["Who taught you to distrust caregivers?", "Why are you refusing to cooperate again?", "Would you prefer a different time, or is something about the shower uncomfortable?", "You understand that I need to finish, don’t you?"], "answer": 2, "explain": "The question opens discussion of timing and discomfort without presuming a motive. Leading, accusatory, and speculative questions undermine clarification.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-039", "chapter": 6, "mode": "care", "topic": "Refusal", "difficulty": 2, "prompt": "A client says shower water felt cold yesterday. Which response best distinguishes a useful hypothesis from an established conclusion?", "choices": ["Cold water explains all future refusals by this client.", "A refusal cannot have more than one contributing factor.", "Yesterday’s experience may contribute to today’s refusal; ask what would help before assuming that is the only reason.", "The client has proved that staff intentionally caused discomfort."], "answer": 2, "explain": "A past experience can inform exploration without proving an exclusive cause. Reflection considers multiple factors and checks interpretations.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-040", "chapter": 6, "mode": "care", "topic": "Person-centred planning", "difficulty": 2, "prompt": "An HCA learns that a client declines morning care because the timing conflicts with a valued routine. What is the most useful reflective learning?", "choices": ["A changed schedule guarantees no further refusal.", "Client routines should be ignored when care is scheduled.", "The HCA’s assumption that one schedule suits everyone needs reconsideration.", "The refusal proves the original care plan was negligent."], "answer": 2, "explain": "The specific learning concerns an assumption about timing and individual needs. It supports coordinated review without a guaranteed outcome or unsupported legal conclusion.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-041", "chapter": 6, "mode": "care", "topic": "Autonomy and scope", "difficulty": 2, "prompt": "A client with a disability declines recommended care. A coworker says, “Their disability means we can decide for them.” Which response is best supported?", "choices": ["An HCA should independently determine capacity before speaking with the team.", "Disability alone does not establish incapacity; report relevant concerns for appropriate assessment and follow authorized processes.", "Family preference automatically resolves the issue.", "Every refusal proves decision-making capacity."], "answer": 1, "explain": "The brief explicitly distinguishes disability from incapacity. Concerns about decision-making require appropriate professionals and processes; neither capacity nor incapacity should be inferred solely from refusal.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-042", "chapter": 6, "mode": "care", "topic": "Autonomy and risk", "difficulty": 2, "prompt": "A client chooses food inconsistent with dietary advice. No immediate emergency is present. Which response best preserves role boundaries?", "choices": ["Ask another client to persuade them.", "Ignore the choice because autonomy removes every reporting duty.", "Confiscate the food because advice is equivalent to an enforceable order.", "Clarify the situation, communicate relevant concerns within scope, and follow the care plan and reporting process without assuming authority to confiscate."], "answer": 3, "explain": "Respect for choice coexists with appropriate communication, reporting, and the care plan. The scenario does not grant authority to confiscate or justify involving an unrelated client.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-043", "chapter": 6, "mode": "care", "topic": "Wound-care refusal", "difficulty": 2, "prompt": "A client declines wound care and says, “It hurt last time.” Which HCA response best supports informed team follow-up?", "choices": ["Perform the care without discussing refusal to prevent infection.", "Acknowledge the reported pain, report the refusal and concern promptly through the appropriate channel, and follow the plan within scope.", "Diagnose osteomyelitis from the refusal.", "Tell the client that sepsis is inevitable if they refuse once."], "answer": 1, "explain": "The concern warrants communication and appropriate escalation, including the pain barrier. Possible complications are not inevitable outcomes, and refusal alone does not diagnose infection.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-044", "chapter": 6, "mode": "care", "topic": "Professional development", "difficulty": 2, "prompt": "During reflection on wound-care refusal, an HCA realizes their own knowledge is limited. Which goal most closely follows the instructor’s professional-development example?", "choices": ["Memorize complications to frighten clients into agreement.", "Avoid reporting until advanced expertise is achieved.", "Learn relevant information through approved education and supervision so observations and concerns can be communicated more effectively.", "Independently take over treatment decisions."], "answer": 2, "explain": "The instructor used reflection to identify wound-care learning needs. Education should improve practice within role, not become a basis for independent treatment decisions or coercion.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-045", "chapter": 6, "mode": "care", "topic": "Emotional regulation", "difficulty": 2, "prompt": "An HCA feels anxious about possible complications after a refusal. Which reflection best separates the worker’s emotion from the client’s decision?", "choices": ["Feeling anxious means the client made the wrong decision.", "If I remain calm, there is no need to report relevant concerns.", "My anxiety authorizes me to override the client.", "I should identify my anxiety, communicate relevant concerns appropriately, and avoid using fear to pressure the client."], "answer": 3, "explain": "Managing anxiety supports clear communication. It neither establishes the right decision nor replaces reporting or authorized procedures.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-046", "chapter": 6, "mode": "care", "topic": "Documentation and scope", "difficulty": 2, "prompt": "A client refuses an intervention after an explanation. Which documentation approach is most defensible?", "choices": ["Omit the refusal if the client appeared calm.", "Document only the worker’s belief that the client understood.", "Record the observed refusal, relevant client words, what was offered or done, and notifications without claiming an assessment outside the HCA’s role.", "Write “fully informed refusal” solely because an HCA gave an explanation."], "answer": 2, "explain": "Objective recording captures the encounter without asserting an independent capacity or informed-consent assessment that was not established. Calmness does not make relevant facts unimportant.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-047", "chapter": 6, "mode": "care", "topic": "Home-care boundaries", "difficulty": 2, "prompt": "A home-care client calls the HCA “the only person who understands me” and asks for private visits outside work. The HCA feels needed. What is the most reflective response?", "choices": ["Recognize the appeal to the HCA’s emotional needs and seek guidance on maintaining the professional relationship and appropriate supports.", "Promise secrecy to preserve trust.", "Tell the client that needing connection is inappropriate.", "Accept because the client initiated the request."], "answer": 0, "explain": "Familiarity and feeling needed can blur boundaries. Acknowledge the need for connection and seek appropriate support without converting the relationship into a private arrangement.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-048", "chapter": 6, "mode": "care", "topic": "Emotional needs", "difficulty": 2, "prompt": "An HCA gives extra attention to a client who offers praise and less attention to a quieter client with comparable planned needs. What is the central reflective concern?", "choices": ["The worker should ask the quieter client to express more gratitude.", "The worker may be allowing a personal need for approval to shape care priorities.", "Praise necessarily invalidates every caring act.", "Quiet clients prefer less care by definition."], "answer": 1, "explain": "The pattern suggests a possible influence of approval-seeking on care. The worker should examine and correct that influence rather than make clients supply praise.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-049", "chapter": 6, "mode": "care", "topic": "Self-worth", "difficulty": 2, "prompt": "A worker reflects, “I want to be useful, and that is why I become upset when a client completes a task independently.” What future response best follows?", "choices": ["Make assistance harder to decline.", "Ask the client to accept unnecessary help to protect the worker’s confidence.", "Support the client’s appropriate independence and find healthy ways to understand personal worth beyond being needed.", "Treat independence as evidence that the care relationship has failed."], "answer": 2, "explain": "The worker’s sense of usefulness should not displace client goals. Reflection can reveal the need and support a different understanding of personal value.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-050", "chapter": 6, "mode": "reflection", "topic": "Reflexivity", "difficulty": 2, "prompt": "A client begins shouting. The HCA notices an urge to match their volume. Which response most directly demonstrates reflexive practice?", "choices": ["Recognize how the urge could shape the interaction and adjust tone in the moment while following safety procedures.", "After the shift, list every insult.", "Assume a quieter voice guarantees safety.", "Explain that the client is responsible for making the HCA angry."], "answer": 0, "explain": "Reflexivity includes examining personal influence while interacting. A calmer response can help but does not guarantee safety or replace procedures.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-051", "chapter": 6, "mode": "defences", "topic": "Strategies versus defences", "difficulty": 2, "prompt": "An HCA chooses a neutral tone before entering a potentially tense encounter. Which interpretation is most precise?", "choices": ["It is displacement because the HCA is changing emotional expression.", "A neutral tone is automatically repression.", "It can be a deliberate communication strategy; the action alone does not establish an unconscious defence mechanism.", "It proves the HCA feels no anxiety."], "answer": 2, "explain": "The brief distinguishes conscious strategies from automatic assignment of defence labels. An observed tone alone does not establish the internal process.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-052", "chapter": 6, "mode": "care", "topic": "Home-visit safety", "difficulty": 2, "prompt": "A home-care worker keeps a phone and keys accessible in accordance with the safety plan. What does this action most clearly demonstrate?", "choices": ["Projection.", "Reaction formation.", "Denial of danger.", "A practical safety precaution."], "answer": 3, "explain": "The action is a deliberate precaution. It should not be labelled an unconscious defence mechanism merely because it helps the worker feel prepared.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-053", "chapter": 6, "mode": "care", "topic": "Safety", "difficulty": 2, "prompt": "A home visit becomes unsafe. Which response best combines professional boundaries and reflection?", "choices": ["Retaliate to demonstrate authority.", "Remain until the task is complete regardless of danger.", "Follow workplace procedures for obtaining help and safely withdrawing, report the situation, and later examine relevant warning signs.", "Write a reflection instead of obtaining help."], "answer": 2, "explain": "Immediate safety procedures take priority; reflection can follow to support learning. It does not replace assistance or authorize retaliation.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-054", "chapter": 6, "mode": "care", "topic": "Source fidelity and safety", "difficulty": 2, "prompt": "An instructor describes receiving two weeks of mentorship before independent home visits. What is the best interpretation for future practice?", "choices": ["After two weeks, no visit can be unsafe.", "Every employer must use exactly two weeks.", "It is an example of supported preparation; actual orientation and supervision requirements depend on the workplace and role.", "Mentorship replaces reading the care plan."], "answer": 2, "explain": "The brief identifies a personal example, not a universal duration or safety guarantee. Preparation remains linked to actual requirements.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-055", "chapter": 6, "mode": "care", "topic": "Advocacy", "difficulty": 2, "prompt": "An HCA observes a recurring difficulty that the visiting clinician has not seen. Which communication best supports advocacy?", "choices": ["On three visits, I observed this specific pattern; here are the client’s words and the assistance needed. Could the team review it?", "I know the diagnosis, so the plan must change immediately.", "The clinician never understands this client.", "I will wait because only clinicians’ observations matter."], "answer": 0, "explain": "Concrete, relevant observations can add information the team lacks. Confident reporting supports advocacy without disparagement or independent diagnosis.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-056", "chapter": 6, "mode": "care", "topic": "Care plan", "difficulty": 2, "prompt": "A care-plan instruction is unclear before a task begins. Which response best demonstrates accountable use of reflection?", "choices": ["Proceed and use reflection later as justification.", "Guess based on what another client usually needs.", "Clarify through the appropriate supervisor or authorized source before proceeding beyond what is understood and permitted.", "Assume the most recent visitor knows the plan."], "answer": 2, "explain": "The instructor emphasizes reading the plan and using appropriate channels. Reflection should reveal a need for clarification, not excuse guessing.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-057", "chapter": 6, "mode": "care", "topic": "Advocacy", "difficulty": 2, "prompt": "An HCA reports a concern accurately but feels dismissed. Which next step best preserves advocacy and role boundaries?", "choices": ["Post the concern online to force a response.", "Stop reporting future observations.", "Change the care plan independently.", "Use the appropriate escalation route, communicate the relevant observations clearly, and document according to policy."], "answer": 3, "explain": "Appropriate escalation maintains communication and accountability. It does not require independent treatment changes or public disclosure.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-058", "chapter": 6, "mode": "care", "topic": "Privacy", "difficulty": 2, "prompt": "A worker considers making a video of a client’s behaviour on a personal phone to prove a concern. No authorization exists. What is the strongest response?", "choices": ["Record as long as the client’s face is excluded.", "Record if the worker’s intention is helpful.", "Ask another client to film it instead.", "Use objective observations and approved reporting routes; do not make the unauthorized recording."], "answer": 3, "explain": "The brief explicitly warns against unauthorized recordings. Good intentions or excluding a face do not by themselves authorize recording or protect confidentiality.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-059", "chapter": 6, "mode": "care", "topic": "Privacy", "difficulty": 2, "prompt": "A visitor begins reading a care plan left open on a table. Which response best supports confidentiality?", "choices": ["Read the rest aloud so no one misunderstands it.", "Assume any visitor has permission.", "Secure the information and follow workplace procedures for addressing the access, without disclosing further details unnecessarily.", "Remove the client’s name but leave every other detail visible."], "answer": 2, "explain": "Access should not be inferred from visitor status. Securing the plan and following the relevant procedure protects information without inventing authority.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-060", "chapter": 6, "mode": "reflection", "topic": "Reflective records", "difficulty": 2, "prompt": "An HCA removes a client’s name from a personal journal but leaves the facility, exact room, date, and a rare event. Which conclusion is best?", "choices": ["The entry is anonymous because there is no name.", "The rare event makes the entry exempt from confidentiality.", "A journal can contain any details if it is handwritten.", "The remaining combination may identify the client; remove identifying client/facility details and use approved reflective practices."], "answer": 3, "explain": "Identifiability depends on the combination of details. The brief specifically cautions against identifying client and facility information in personal reflections.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-061", "chapter": 6, "mode": "care", "topic": "Documentation", "difficulty": 2, "prompt": "Which sentence belongs most appropriately in personal reflective analysis rather than being treated as an objective clinical fact?", "choices": ["Client turned away when assistance was offered.", "Supervising nurse notified at 09:15.", "I wonder whether my fear of criticism made me interrupt.", "Client stated, “I want to wait.”"], "answer": 2, "explain": "The sentence is an introspective hypothesis about the worker. The others describe statements, actions, or notification. Personal analysis and objective care documentation serve different purposes.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-062", "chapter": 6, "mode": "care", "topic": "Treatment preferences", "difficulty": 2, "prompt": "A client expresses a treatment preference that appears inconsistent with the current documented orders. What should the HCA do?", "choices": ["Promptly report the statement through the appropriate channel and follow current authorized orders, care plans, and applicable emergency procedures.", "Choose the order that best matches the HCA’s personal values.", "Treat the statement as an independently completed order change.", "Ignore the statement because orders cannot be reviewed."], "answer": 0, "explain": "Preferences should be communicated for appropriate review. An HCA should not assume the statement itself independently revises an order or disregard the expressed concern.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-063", "chapter": 6, "mode": "care", "topic": "Communication between settings", "difficulty": 2, "prompt": "An HCA notices that transfer information and the current care plan appear inconsistent. What is the best response?", "choices": ["Ask a visitor to choose which instructions apply.", "Report and seek clarification through authorized channels, following applicable procedures for the current situation.", "Delete the conflicting instruction from the record.", "Select whichever document has the clearest handwriting."], "answer": 1, "explain": "Possible discrepancies need authorized clarification. The HCA should not resolve them by arbitrary selection, visitor preference, or unilateral editing.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-064", "chapter": 6, "mode": "care", "topic": "Treatment orders", "difficulty": 2, "prompt": "A family member says, “You heard the client’s new wishes, so you can change the treatment order yourself.” Which reply best reflects role boundaries?", "choices": ["Verbal preferences are never relevant.", "Only family wishes can change an order.", "I can report what was expressed and seek the appropriate review; I cannot independently change the order.", "Any worker may change an order if they document it."], "answer": 2, "explain": "The appropriate contribution is reporting and facilitating review within role. The other replies create unsupported absolutes or authority.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-065", "chapter": 6, "mode": "care", "topic": "End-of-life scope", "difficulty": 2, "prompt": "An HCA encounters an unresponsive client in circumstances they did not expect. Which response is best?", "choices": ["Delay action until a reflective journal entry is complete.", "Independently pronounce death before reporting.", "Follow the applicable emergency/reporting procedures, care plan, and authorized directions; do not independently pronounce death.", "Assume every unexpected death requires an autopsy before taking any action."], "answer": 2, "explain": "The brief emphasizes emergency/reporting procedures and the limit on independent pronouncement. It does not establish a universal autopsy requirement or justify delay.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-066", "chapter": 6, "mode": "care", "topic": "End-of-life scope", "difficulty": 2, "prompt": "An expected-death care plan is in place. Which statement best describes the HCA’s responsibility?", "choices": ["Decide privately whether the family needs notification.", "Expected death eliminates all reporting requirements.", "Use the same assumptions for every client regardless of their plan.", "Follow the applicable plan and procedures and communicate observations; expected circumstances do not confer authority to pronounce death independently."], "answer": 3, "explain": "An expected situation still requires role-appropriate actions and reporting. The plan matters, and independent pronouncement is outside the role described.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-067", "chapter": 6, "mode": "care", "topic": "Accountability", "difficulty": 2, "prompt": "A coworker says, “If I follow the plan and chart everything, I cannot be held accountable for negligence.” What is the strongest correction?", "choices": ["Accurate records replace appropriate care.", "Documentation makes all actions legally safe.", "Following the plan, reporting, and accurate documentation matter, but they do not guarantee immunity from liability.", "Accountability applies only when nothing is written."], "answer": 2, "explain": "The source brief explicitly rejects a guarantee of immunity. The quiz does not determine liability in any particular case.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-068", "chapter": 6, "mode": "reflection", "topic": "Grief and reflection", "difficulty": 2, "prompt": "An HCA wishes to reflect on a death that felt more distressing than expected. What is the most useful focus?", "choices": ["Whether feeling sadness proves the HCA is unfit.", "A detailed account shared with unrelated friends for verification.", "A diagnosis of every grieving family member.", "Personal triggers, expectations, professional actions, support needs, and learning, with confidentiality maintained."], "answer": 3, "explain": "Reflection can support emotional processing and professional learning without equating sadness with failure or disclosing client information inappropriately.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-069", "chapter": 6, "mode": "defences", "topic": "Suppression", "difficulty": 2, "prompt": "While supporting a grieving family, an HCA recognizes distress and temporarily sets it aside to complete assigned responsibilities, intending to process it with appropriate support later. Which additional detail most strengthens the interpretation of suppression?", "choices": ["The HCA later acknowledges and works through the distress.", "The HCA insists nothing distressing occurred.", "The HCA redirects anger toward another client.", "The HCA cannot consciously recognize the distress at any point."], "answer": 0, "explain": "Returning to a recognized feeling supports temporary suppression rather than denial, unconscious repression, or displacement.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-070", "chapter": 6, "mode": "defences", "topic": "Anticipation", "difficulty": 2, "prompt": "Before a stressful shift, a worker imagines likely communication challenges and rehearses suitable responses. Afterward, they review what happened. Which pairing is best?", "choices": ["Anticipation before the shift; reflection afterward.", "Displacement before the shift; repression afterward.", "Humour before the shift; fantasy afterward.", "Projection before the shift; denial afterward."], "answer": 0, "explain": "Preparing for expected stress illustrates anticipation; examining an actual experience afterward illustrates reflection. Activities may work together without being identical.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-071", "chapter": 6, "mode": "defences", "topic": "Altruism", "difficulty": 2, "prompt": "A worker volunteers to help others but becomes resentful when nobody praises them. Which interpretation is most careful?", "choices": ["Every volunteer action is displacement.", "Resentment proves the worker has no concern for others.", "The expectation of praise warrants reflection on approval-seeking; do not assume the help was entirely selfless.", "The action conclusively demonstrates selfless altruism."], "answer": 2, "explain": "The defining cue for altruism is selfless concern without seeking personal reward. Mixed motives require examination, not a categorical judgment that the person has no concern.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-072", "chapter": 6, "mode": "defences", "topic": "Humour", "difficulty": 2, "prompt": "A client responds to a joke with silence and turns away. What is the best next response?", "choices": ["Explain that the client should appreciate humour.", "Notice the response, check whether the remark was unwelcome, and adjust respectfully.", "Conclude that all humour in healthcare is inappropriate.", "Repeat the joke more loudly."], "answer": 1, "explain": "Appropriate humour depends on the person and situation. Observed discomfort calls for checking and adjusting, not defending intent or imposing a blanket ban.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-073", "chapter": 6, "mode": "defences", "topic": "Humour", "difficulty": 2, "prompt": "A worker uses sarcasm about a client’s fear and calls it a mature defence. What distinction matters most?", "choices": ["Humour is mature only when every observer laughs.", "Any speech during stress is sublimation.", "Mature humour relieves tension without dismissing pain; sarcasm that belittles fear may undermine care.", "A mature label automatically makes the action beneficial."], "answer": 2, "explain": "The effect and context of humour matter. A defence label does not excuse insensitive conduct, and laughter is not the sole measure of appropriateness.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-074", "chapter": 6, "mode": "defences", "topic": "Sublimation", "difficulty": 2, "prompt": "After an insult, a worker states a respectful limit and obtains help. Later, they channel aggressive energy into a safe sport. Which action most specifically illustrates sublimation?", "choices": ["Obtaining help.", "Channelling the aggressive impulse into the acceptable sporting activity.", "Recognizing that an insult occurred.", "Stating the limit."], "answer": 1, "explain": "Sublimation is the transformation of an unacceptable impulse into an acceptable outlet. Safety actions and awareness are appropriate but are not automatically the same mechanism.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-075", "chapter": 6, "mode": "defences", "topic": "Suppression and avoidance", "difficulty": 2, "prompt": "A worker says, “I postponed thinking about my distress,” but never returns to it and repeatedly avoids every reminder. Which interpretation is best?", "choices": ["Avoidance always improves communication.", "The statement alone establishes effective suppression with resolution.", "This proves unconscious repression beyond doubt.", "The repeated avoidance warrants further reflection; temporary postponement has not clearly led to later processing."], "answer": 3, "explain": "The course definition emphasizes setting aside temporarily and returning later. The pattern raises concern without establishing a specific unconscious mechanism or diagnosis.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-076", "chapter": 6, "mode": "care", "topic": "Mature distinctions", "difficulty": 2, "prompt": "Which pairing correctly matches two mature responses to their decisive cues?", "choices": ["Anticipation—refusing to accept past events; suppression—unconscious removal of memories.", "Humour—denying seriousness; altruism—seeking praise.", "Altruism—attributing anger to others; anticipation—redirecting anger to a housemate.", "Suppression—temporary conscious postponement; sublimation—acceptable channelling of an unacceptable impulse."], "answer": 3, "explain": "The correct pair preserves awareness/postponement for suppression and constructive channelling for sublimation. Other pairs confuse projection, displacement, denial, and repression.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-077", "chapter": 6, "mode": "care", "topic": "Displacement correction", "difficulty": 2, "prompt": "A worker says, “I noticed another person’s inadequacies, so that is displacement.” Which correction is most precise?", "choices": ["Noticing inadequacies alone defines projection.", "Displacement means any critical thought.", "Displacement redirects strong feelings toward a substitute target; noticing shortcomings alone establishes neither displacement nor projection.", "Projection and displacement are synonyms."], "answer": 2, "explain": "This corrects the instructor’s false statement without replacing it with another misdefinition. Projection requires attributing one’s own unacceptable feelings or characteristics to another.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-078", "chapter": 6, "mode": "defences", "topic": "Other mechanisms", "difficulty": 2, "prompt": "A worker avoids a real-life problem by repeatedly imagining a satisfying world in which the problem does not exist, without insisting that the imagined world is real. Which chapter response fits best?", "choices": ["Anticipation.", "Fantasy.", "Altruism.", "Suppression."], "answer": 1, "explain": "The chapter describes fantasy as an imagined world meeting needs not met by reality. Anticipation prepares for actual future difficulty rather than substituting an imagined world.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-079", "chapter": 6, "mode": "reflection", "topic": "Critical reflection", "difficulty": 2, "prompt": "An HCA receives praise after an interaction in which the client appeared rushed. What is the most critically reflective response?", "choices": ["Assume a rushed appearance establishes the client’s feelings.", "Consider the feedback alongside the client’s responses, intentions, and other evidence before deciding what to retain or change.", "Discard all positive feedback.", "Praise proves the care was fully person-centred."], "answer": 1, "explain": "Reflection uses more than one perspective while separating observations from inferred feelings. Positive feedback can be useful without making further examination unnecessary.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-080", "chapter": 6, "mode": "reflection", "topic": "Self, Person, environment", "difficulty": 2, "prompt": "An HCA’s reflection identifies communication style, personality, beliefs, and emotional responses. What additional dimension prevents the account from becoming exclusively self-focused?", "choices": ["Assume everyone shares the HCA’s goals.", "Consider the client’s perspective and relevant environmental and relational factors.", "Replace every observation with a personality label.", "Ignore the client because reflection concerns the self."], "answer": 1, "explain": "Self-awareness is central, but the chapter also examines the Person and environment, expectations, and effects of the interaction.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-081", "chapter": 6, "mode": "reflection", "topic": "What Why How", "difficulty": 2, "prompt": "A worker asks, “What happened? Why did I react this way? How can I respond more constructively?” What makes these questions useful?", "choices": ["They connect description, understanding, and future response rather than stopping at blame.", "They guarantee a single correct solution for every client.", "They prove that the other person’s conduct is acceptable.", "They remove the need for evidence."], "answer": 0, "explain": "The instructor’s What/Why/How emphasis supports inquiry into events, causes, and action. These prompts do not guarantee a universal formula or excuse harmful conduct.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-082", "chapter": 6, "mode": "reflection", "topic": "Value and needs", "difficulty": 2, "prompt": "An HCA says, “My worth depends on whether clients need me today.” Which reflective challenge most closely addresses that belief?", "choices": ["Examine how worth, importance, and usefulness are being understood and whether self-respect has become dependent on client approval or dependence.", "Ask clients to validate the HCA at each visit.", "Increase client dependence to restore worth.", "Assume the belief must be true because it feels powerful."], "answer": 0, "explain": "The brief highlights value and the chapter links individual worth to self-understanding and self-respect. Reflection can challenge reliance on clients to validate worth.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-083", "chapter": 6, "mode": "reflection", "topic": "Journaling", "difficulty": 2, "prompt": "A reflective journal shows that the HCA becomes abrupt late in noisy shifts. What is the strongest next inference?", "choices": ["The worker’s personality cannot change.", "The pattern should be removed from the journal because it is uncomfortable.", "The pattern suggests factors to explore and address, while considering other influences and testing a practical change.", "Noise conclusively causes every abrupt response."], "answer": 2, "explain": "Patterns generate useful hypotheses, not proof of a sole cause. Journaling supports development when linked to analysis and action.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-084", "chapter": 6, "mode": "reflection", "topic": "Reflective habit", "difficulty": 2, "prompt": "After months of regular reflection, an HCA completes a thoughtful review more quickly. What conclusion best fits the chapter?", "choices": ["Practice may make reflection more efficient, provided depth and learning remain.", "Faster reflection must be superficial.", "Reflection is no longer needed.", "Only lengthy writing counts as reflection."], "answer": 0, "explain": "The chapter notes that time may decrease with practice. Neither speed nor length alone establishes quality.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-085", "chapter": 6, "mode": "reflection", "topic": "Positive reflection", "difficulty": 2, "prompt": "An HCA chooses to reflect only on encounters that felt embarrassing. What important learning opportunity is being missed?", "choices": ["Reflection on strengths prevents improvement.", "Successful encounters require no examination of context.", "Only embarrassing events reveal emotion.", "Positive experiences can reveal effective actions worth repeating."], "answer": 3, "explain": "Reflection includes positive and negative experiences. Understanding successful communication supports deliberate repetition and identification of strengths.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-086", "chapter": 6, "mode": "care", "topic": "Necessity and scope", "difficulty": 2, "prompt": "A worker realizes a repeated intervention adds no benefit and seems to irritate the client. What is the best reflective next step?", "choices": ["Continue without reporting because reflection is private.", "Conclude that all care is unnecessary.", "Examine its purpose and effects, then raise a justified concern for appropriate review rather than assuming authority to change the plan.", "Stop any prescribed intervention independently."], "answer": 2, "explain": "Reflection may identify an unnecessary or unsuitable element, but resulting changes must respect role and authorized review.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-087", "chapter": 6, "mode": "reflection", "topic": "Cycle application", "difficulty": 2, "prompt": "An HCA has selected an event and described it. Which prompt most clearly advances the cycle toward exploring all reactions?", "choices": ["Which model name sounds most professional?", "What proves the client was unreasonable?", "How can I avoid identifying my own response?", "What did I and the client say or show, what might those reactions mean, and how can I check my interpretation?"], "answer": 3, "explain": "Exploration includes self and Person and distinguishes observed responses from inferred meaning. It is broader than proving blame or naming a model.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-088", "chapter": 6, "mode": "care", "topic": "Circular process", "difficulty": 2, "prompt": "A worker says the seven-step cycle is complete forever once a plan is applied. Which correction is best?", "choices": ["The cycle stops at goal setting.", "Application generates further experience to reflect on, so learning continues.", "A plan must never be applied.", "Only a new workplace allows the cycle to restart."], "answer": 1, "explain": "The instructor emphasizes continuous, circular operation. Action informs the next round of reflection and adjustment.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-089", "chapter": 6, "mode": "reflection", "topic": "Cycle first step", "difficulty": 2, "prompt": "A student begins a seven-step account with choosing an event but omits any commitment to reflection. Which course element is missing before event selection?", "choices": ["Documenting a predetermined outcome.", "Choosing and allocating time to reflect.", "Choosing the final answer.", "Deciding the client’s diagnosis."], "answer": 1, "explain": "The verified diagram begins with choosing and allocating time to reflect on healthcare practice, then choosing a challenging or interesting event.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-090", "chapter": 6, "mode": "care", "topic": "Model distinction", "difficulty": 2, "prompt": "Which statement best distinguishes the seven-step cycle from the supplied Johns model?", "choices": ["Johns begins with choosing time, while the cycle never involves action.", "The cycle begins with choosing/allocating time and moves through goals, plans, and action; Johns supplies seven structured lines of examination of an experience.", "They must have identical labels because each has seven parts.", "Only Johns allows any learning."], "answer": 1, "explain": "Both guide reflection, but their structures differ. The chapter supplies Johns’s description, causes, background, aims, consequences/feelings, alternatives, and learning.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-091", "chapter": 6, "mode": "care", "topic": "Depth versus checklist", "difficulty": 2, "prompt": "A student writes seven Johns headings and answers each with “the client was difficult.” What is the main problem?", "choices": ["Johns excludes any consideration of the client.", "The structure has been used mechanically without examining evidence, personal contribution, context, or learning.", "The correct number of headings guarantees depth.", "Reflection should always avoid uncomfortable events."], "answer": 1, "explain": "Johns is intended to deepen understanding, not merely complete a format. Repeated judgment does not supply the analysis the headings invite.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-092", "chapter": 6, "mode": "reflection", "topic": "Johns aims and effects", "difficulty": 2, "prompt": "An HCA intended to reassure a client but spoke over them. The client withdrew. Which reflection best integrates intention and consequence?", "choices": ["Good intent means there was no communication problem.", "Only the client’s reaction matters; the worker’s aim is irrelevant.", "Withdrawal proves the client wanted no care.", "Examine the reassuring aim alongside the interruption and withdrawal, and explore how another approach might have affected the encounter."], "answer": 3, "explain": "Both aims and consequences are relevant. Neither good intention nor an observed response alone gives a complete account of meaning.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-093", "chapter": 6, "mode": "reflection", "topic": "Johns background", "difficulty": 2, "prompt": "An HCA examines whether a previous conflict, fatigue, and corridor noise affected an encounter. Which Johns element is most directly addressed?", "choices": ["Alternative actions only.", "The final action plan only.", "Relevant background and environmental information.", "Future learning only."], "answer": 2, "explain": "The focus is on significant circumstances relating to people and environment. Other elements may later use this information, but are not the explicit focus here.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-094", "chapter": 6, "mode": "reflection", "topic": "Reflexivity and position", "difficulty": 2, "prompt": "During an interaction, an HCA notices that their professional authority may be discouraging disagreement and explicitly invites the client’s preference. What does this most clearly illustrate?", "choices": ["An objective diagnosis of the client’s motive.", "Denial that the interaction has any power difference.", "Reflexive attention to the practitioner’s position and influence.", "Displacement of the client’s emotion."], "answer": 2, "explain": "The brief emphasizes reflexivity as examining assumptions, position, and influence. This can occur in the moment and guide an adjustment.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-095", "chapter": 6, "mode": "reflection", "topic": "Non-verbal self-awareness", "difficulty": 2, "prompt": "A worker says, “I was calm, so my non-verbal communication could not have affected the client.” What is the best response?", "choices": ["Non-verbal cues do not belong in reflection.", "Personal emotional state and others’ perceptions can differ; examine posture, timing, expression, and the client’s response.", "A calm feeling proves the client perceived reassurance.", "Only spoken words affect interactions."], "answer": 1, "explain": "Reflection includes non-verbal behaviour and its possible influence. The worker’s internal calm does not establish how the interaction was experienced.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-096", "chapter": 6, "mode": "reflection", "topic": "Changing intentions", "difficulty": 2, "prompt": "A family meeting plan assumes that everyone still shares the same goal, although a recent event may have changed one person’s expectations. What should be clarified?", "choices": ["How to obtain agreement before hearing concerns.", "Whether emotions can be excluded from the discussion.", "Each participant’s current intentions, concerns, and understanding rather than relying solely on the earlier agreement.", "Which family member can be blamed for delaying the meeting."], "answer": 2, "explain": "The chapter emphasizes checking purposes and expectations initially and throughout interaction, especially when events and emotions may have changed them.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-097", "chapter": 6, "mode": "truefalse", "topic": "Outcomes", "difficulty": 2, "prompt": "A reflection can justify retaining an effective action rather than changing every part of care.", "choices": ["True", "False"], "answer": 0, "explain": "Reflection identifies strengths as well as shortcomings; positive actions may be deliberately reinforced.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-098", "chapter": 6, "mode": "truefalse", "topic": "Johns model", "difficulty": 2, "prompt": "In Johns’s model, considering alternative actions includes asking why those alternatives were not chosen.", "choices": ["True", "False"], "answer": 0, "explain": "The alternatives element includes barriers to choosing them and their possible consequences, not merely listing options.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-099", "chapter": 6, "mode": "truefalse", "topic": "Emotional needs", "difficulty": 2, "prompt": "If an HCA correctly identifies a personal emotional need, it is appropriate to make the client responsible for meeting that need.", "choices": ["True", "False"], "answer": 1, "explain": "Awareness should support appropriate management of needs rather than shifting responsibility to the client.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-100", "chapter": 6, "mode": "truefalse", "topic": "Defences", "difficulty": 2, "prompt": "An HCA who consciously postpones a distressing thought and returns to it later is demonstrating repression.", "choices": ["True", "False"], "answer": 1, "explain": "That pattern is suppression. Repression is unconscious exclusion from awareness.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-101", "chapter": 6, "mode": "truefalse", "topic": "Defences", "difficulty": 2, "prompt": "One episode resembling projection is sufficient to establish a psychiatric diagnosis.", "choices": ["True", "False"], "answer": 1, "explain": "A teaching example of a defence mechanism is not a diagnostic assessment.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-102", "chapter": 6, "mode": "truefalse", "topic": "Confidentiality", "difficulty": 2, "prompt": "Because a colleague is also a healthcare worker, sharing identifiable client information with them is automatically appropriate.", "choices": ["True", "False"], "answer": 1, "explain": "Role alone is insufficient: purpose, authorization, relevance, setting, and applicable policy matter.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-103", "chapter": 6, "mode": "truefalse", "topic": "Documentation", "difficulty": 2, "prompt": "Objective documentation may include a relevant direct client quotation, clearly identified as the client’s words.", "choices": ["True", "False"], "answer": 0, "explain": "A properly attributed quote can record what was said without turning it into an inferred motive.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-104", "chapter": 6, "mode": "truefalse", "topic": "Reflection", "difficulty": 2, "prompt": "Feeling upset during reflection proves the reflective process is ineffective.", "choices": ["True", "False"], "answer": 1, "explain": "Reflection can be uncomfortable while revealing meaningful causes and opportunities for change. Its usefulness depends on depth and learning, not absence of discomfort.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-105", "chapter": 6, "mode": "truefalse", "topic": "Reflexivity", "difficulty": 2, "prompt": "Reflexive practice includes examining how one’s assumptions and professional position influence an interaction.", "choices": ["True", "False"], "answer": 0, "explain": "The brief foregrounds assumptions, position, and influence; the chapter also highlights reflecting while interacting.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-106", "chapter": 6, "mode": "truefalse", "topic": "Cycle", "difficulty": 2, "prompt": "The first step of the course’s seven-step reflective cycle is choosing and allocating time to reflect.", "choices": ["True", "False"], "answer": 0, "explain": "This is directly shown in the recovered slideshow diagram.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-107", "chapter": 6, "mode": "truefalse", "topic": "Models", "difficulty": 2, "prompt": "Having seven elements means Johns’s model and the seven-step reflective cycle must have identical wording and sequence.", "choices": ["True", "False"], "answer": 1, "explain": "Their structures differ even though both have seven elements.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-108", "chapter": 6, "mode": "truefalse", "topic": "Anticipation", "difficulty": 2, "prompt": "Preparing responses for an expected difficult meeting can illustrate anticipation.", "choices": ["True", "False"], "answer": 0, "explain": "Preparation for anticipated stress is the key cue.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-109", "chapter": 6, "mode": "truefalse", "topic": "Defences", "difficulty": 2, "prompt": "Sublimation means redirecting anger from a supervisor toward a less powerful person.", "choices": ["True", "False"], "answer": 1, "explain": "That describes displacement; sublimation channels the impulse into an acceptable outlet.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-110", "chapter": 6, "mode": "truefalse", "topic": "Suppression", "difficulty": 2, "prompt": "Suppression requires permanently eliminating an emotion from conscious awareness.", "choices": ["True", "False"], "answer": 1, "explain": "The course describes temporary postponement with a later return.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-111", "chapter": 6, "mode": "truefalse", "topic": "Humour", "difficulty": 2, "prompt": "A joke can be inappropriate even if the worker intended to relieve tension.", "choices": ["True", "False"], "answer": 0, "explain": "Intent alone does not establish sensitivity or benefit; context and responses matter.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-112", "chapter": 6, "mode": "truefalse", "topic": "Defences", "difficulty": 2, "prompt": "Choosing a neutral tone automatically demonstrates an unconscious defence mechanism.", "choices": ["True", "False"], "answer": 1, "explain": "It can be a conscious communication strategy; the action alone does not establish the psychological mechanism.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-113", "chapter": 6, "mode": "truefalse", "topic": "Preference", "difficulty": 2, "prompt": "A client’s preference for a caregiver of a particular gender should automatically be documented as personal hostility toward the assigned HCA.", "choices": ["True", "False"], "answer": 1, "explain": "Record the stated preference and relevant facts without inferring hostility.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-114", "chapter": 6, "mode": "truefalse", "topic": "Capacity", "difficulty": 2, "prompt": "Disability alone is sufficient evidence that a client cannot make a particular decision.", "choices": ["True", "False"], "answer": 1, "explain": "The brief explicitly rejects this inference; concerns require appropriate assessment.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-115", "chapter": 6, "mode": "truefalse", "topic": "Refusal", "difficulty": 2, "prompt": "Respecting choice removes every responsibility to communicate or report concerns.", "choices": ["True", "False"], "answer": 1, "explain": "Respect for choice and role-appropriate reporting can both be necessary.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-116", "chapter": 6, "mode": "truefalse", "topic": "Risk language", "difficulty": 2, "prompt": "One refusal of wound care makes sepsis an inevitable outcome.", "choices": ["True", "False"], "answer": 1, "explain": "The brief discusses possible risks, not an inevitable consequence of a single refusal.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-117", "chapter": 6, "mode": "truefalse", "topic": "Boundaries", "difficulty": 2, "prompt": "An HCA’s anxiety about a refusal is, by itself, authority to override the client.", "choices": ["True", "False"], "answer": 1, "explain": "Anxiety calls for regulation and appropriate reporting, not assumed authority.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-118", "chapter": 6, "mode": "truefalse", "topic": "Confidentiality", "difficulty": 2, "prompt": "A personal reflection should avoid identifying client and facility details.", "choices": ["True", "False"], "answer": 0, "explain": "The brief explicitly emphasizes this safeguard; official records follow workplace rules.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-119", "chapter": 6, "mode": "truefalse", "topic": "Privacy", "difficulty": 2, "prompt": "Removing a name always makes a detailed client story anonymous.", "choices": ["True", "False"], "answer": 1, "explain": "Unique facts and combinations of details can still identify a person.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-120", "chapter": 6, "mode": "truefalse", "topic": "Privacy", "difficulty": 2, "prompt": "A helpful intention alone authorizes audio or video recording of a client.", "choices": ["True", "False"], "answer": 1, "explain": "The brief warns against unauthorized recording; intention does not supply authorization.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-121", "chapter": 6, "mode": "truefalse", "topic": "Advocacy", "difficulty": 2, "prompt": "An HCA may contribute valuable observations even when a visiting clinician has not seen the same events.", "choices": ["True", "False"], "answer": 0, "explain": "Objective observations can inform team review and advocacy.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-122", "chapter": 6, "mode": "truefalse", "topic": "Advocacy", "difficulty": 2, "prompt": "Confident advocacy requires an HCA to make a diagnosis before reporting a concern.", "choices": ["True", "False"], "answer": 1, "explain": "Relevant observations can be reported confidently within role without an independent diagnosis.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-123", "chapter": 6, "mode": "truefalse", "topic": "Orders", "difficulty": 2, "prompt": "A verbal statement of changed treatment preferences should be reported rather than assumed to independently revise an existing order.", "choices": ["True", "False"], "answer": 0, "explain": "The brief emphasizes communication and authorized review while following applicable orders and protocols.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-124", "chapter": 6, "mode": "truefalse", "topic": "End of life", "difficulty": 2, "prompt": "An expected-death plan gives an HCA independent authority to pronounce death.", "choices": ["True", "False"], "answer": 1, "explain": "The brief expressly states that HCAs do not independently pronounce death.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-125", "chapter": 6, "mode": "truefalse", "topic": "End of life", "difficulty": 2, "prompt": "Every unexpected death automatically requires an autopsy or coroner attendance.", "choices": ["True", "False"], "answer": 1, "explain": "The brief rejects that universal claim; applicable procedures and authorized decisions govern the response.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-126", "chapter": 6, "mode": "truefalse", "topic": "Accountability", "difficulty": 2, "prompt": "Following a care plan and writing accurate notes guarantees immunity from liability.", "choices": ["True", "False"], "answer": 1, "explain": "These actions are important but do not create a universal immunity guarantee.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-127", "chapter": 6, "mode": "truefalse", "topic": "Safety", "difficulty": 2, "prompt": "The instructor’s example of a two-week mentorship establishes a universal minimum orientation period for every home-care employer.", "choices": ["True", "False"], "answer": 1, "explain": "It was an example, not a verified universal rule.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-128", "chapter": 6, "mode": "truefalse", "topic": "Development", "difficulty": 2, "prompt": "Reflection can identify a learning need without authorizing independent practice beyond one’s role.", "choices": ["True", "False"], "answer": 0, "explain": "Learning and supervision should support appropriate practice within role.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-129", "chapter": 6, "mode": "truefalse", "topic": "Outcomes", "difficulty": 2, "prompt": "A positive outcome means every individual action during the encounter was necessary.", "choices": ["True", "False"], "answer": 1, "explain": "Details and consequences still require examination, including potentially unnecessary or harmful actions.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-130", "chapter": 6, "mode": "truefalse", "topic": "Needs", "difficulty": 2, "prompt": "Personal emotional needs should be acknowledged and managed without making clients responsible for fulfilling them.", "choices": ["True", "False"], "answer": 0, "explain": "This is a central chapter and instructor emphasis.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-131", "chapter": 6, "mode": "truefalse", "topic": "Self-awareness", "difficulty": 2, "prompt": "An HCA who feels rejected by a refusal should treat that feeling as proof of the client’s intention.", "choices": ["True", "False"], "answer": 1, "explain": "A personal feeling is not evidence of another person’s motive; clarify and examine assumptions.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-132", "chapter": 6, "mode": "truefalse", "topic": "Journaling", "difficulty": 2, "prompt": "Reflection may become quicker with practice while still requiring honest attention and commitment.", "choices": ["True", "False"], "answer": 0, "explain": "Efficiency can develop; depth should be retained.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-133", "chapter": 6, "mode": "truefalse", "topic": "Models", "difficulty": 2, "prompt": "A reflective model supplies one guaranteed response for every future situation.", "choices": ["True", "False"], "answer": 1, "explain": "The chapter presents models as guides to insight, not one-answer-fits-all formulas.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-134", "chapter": 6, "mode": "truefalse", "topic": "Boundaries", "difficulty": 2, "prompt": "Setting a respectful limit during abuse can coexist with responsibility for managing one’s own reactions.", "choices": ["True", "False"], "answer": 0, "explain": "Personal accountability does not require accepting abuse or disregarding safety procedures.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-135", "chapter": 6, "mode": "scenarios", "topic": "Integrated refusal", "difficulty": 2, "prompt": "A client declines a non-urgent shower because they are exhausted. The HCA feels a need to be trusted and wants to keep persuading until the client agrees. Which plan best integrates reflection, client choice and continuity of care?", "choices": ["Recognize the need for approval, clarify the client’s preferences without coercion, explore appropriate options, and report/document the relevant facts under policy.", "Respect the refusal by ending the discussion and assume there is no need to communicate relevant concerns to the team.", "Offer reassurance, continue persuading until agreement, and record the eventual acceptance as evidence that the concern was resolved.", "Accept the refusal as a rejection of the HCA, arrange a different worker, and omit the emotional reaction from further reflection."], "answer": 0, "explain": "The worker should examine approval-seeking without making the client meet that need. Respectful clarification, appropriate options, communication and objective documentation support person-centred care. Respecting choice does not eliminate relevant reporting responsibilities.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-136", "chapter": 6, "mode": "scenarios", "topic": "Critical reflection", "difficulty": 2, "prompt": "After a difficult conversation, an HCA writes, “The client was aggressive because they hate dependence. I stayed calm, so I did nothing to contribute.” Which revision most improves the reflection?", "choices": ["Delete all observations about the client and focus entirely on the HCA’s feelings without planning any future response.", "Describe specific words/actions, treat the proposed motive as a hypothesis, examine the HCA’s contribution and context, and identify a future approach to evaluate.", "Replace “aggressive” with “upset” and retain the conclusion that calmness proves the HCA had no influence.", "Keep the motive as a fact but add the client’s age and diagnosis to explain the behaviour."], "answer": 1, "explain": "The original account combines a broad label, an unverified motive and an unsupported conclusion about the worker. Reflection separates observation from inference and examines personal contribution, context and future learning. Calmness does not prove that communication was helpful.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-137", "chapter": 6, "mode": "scenarios", "topic": "Johns synthesis", "difficulty": 2, "prompt": "A family meeting produces an agreed care plan, but a participant becomes silent after an interruption. Which sequence best represents a complete Johns-model examination?", "choices": ["Describe the event; explore causes and purpose; consider background; examine aims; consider consequences and feelings; examine alternatives and why they were not chosen; identify learning for future reactions.", "Describe the agreement; identify who caused the silence; choose a more efficient meeting format; confirm that agreement proves success.", "Allocate reflection time; select an event; describe it; explore reactions; establish goals; develop plans; act on them.", "Describe the event; review background and aims; record the final agreement; stop because the practical goal was achieved."], "answer": 0, "explain": "Johns’s seven elements include causes, context, aims, consequences/feelings, alternatives and future learning. The time–event–goals–plans–action sequence is the other reflective cycle. Agreement alone does not establish that everyone felt heard.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-138", "chapter": 6, "mode": "scenarios", "topic": "Cycle synthesis", "difficulty": 2, "prompt": "An HCA rushes morning care when anxious about appearing slow. Which plan most fully completes the seven-step reflective cycle?", "choices": ["Describe the rushing, select a strategy immediately, and assume improvement because the strategy was well intended.", "Allocate time, identify anxiety, and repeat the reflection until anxiety disappears before establishing any goal.", "Allocate time, select and describe an encounter, explore all reactions, establish an observable goal, develop feasible strategies, then apply and review them.", "Set a general goal to be better, apply it without a strategy, and judge success only by whether the worker feels efficient."], "answer": 2, "explain": "The cycle begins with choosing/allocating time and selecting an event, then links description and exploration of reactions to goals, plans and action. Application produces further experience for reflection. Observable goals and feasible strategies make the learning reviewable.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-139", "chapter": 6, "mode": "scenarios", "topic": "Defence comparison", "difficulty": 2, "prompt": "Following criticism, a worker (1) shouts at a housemate, (2) channels aggressive energy into squash, (3) consciously postpones distress until a debrief and returns to it, and (4) attributes their own unacknowledged anger to the supervisor. Which sequence correctly identifies the four responses?", "choices": ["Sublimation; displacement; suppression; reaction formation.", "Projection; displacement; repression; sublimation.", "Displacement; anticipation; denial; projection.", "Displacement; sublimation; suppression; projection."], "answer": 3, "explain": "Displacement redirects emotion unhealthily to another target; sublimation channels the impulse into an acceptable outlet; suppression temporarily postpones recognized distress; projection attributes one’s own unacknowledged feeling to another. These stipulated examples are not diagnoses.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-140", "chapter": 6, "mode": "scenarios", "topic": "Confidentiality synthesis", "difficulty": 2, "prompt": "An HCA drafts a personal reflection containing a client’s name, room, rare condition and family details, intending to email it to a friend who formerly worked in healthcare. Which revision best protects confidentiality while preserving learning?", "choices": ["Send only a copy of the care record so the friend can independently assess the client before discussing the worker’s feelings.", "Use an appropriate authorized support route and approved private method, limit identifying information, and focus reflection on the worker’s reactions and learning.", "Remove the name but retain the room and rare condition, because former healthcare workers may receive any de-identified story.", "Keep all details but ask the friend to promise secrecy before opening the personal email."], "answer": 1, "explain": "Professional support should use an authorized route and appropriate information handling. Removing a name may not prevent identification. Former employment, good intentions and promises of secrecy do not by themselves authorize disclosure.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-141", "chapter": 6, "mode": "scenarios", "topic": "Gender preference synthesis", "difficulty": 2, "prompt": "A client requests a female worker for intimate care. The male HCA feels embarrassed and interprets this as incompetence. Which response best addresses both care and self-awareness?", "choices": ["Record hostility toward male staff and ask the team to avoid discussing the request with the client again.", "Promise that only female workers will attend from now on, because acknowledging a preference requires guaranteeing it.", "Acknowledge the preference, question the personal interpretation, seek supervisory guidance on available options, and document relevant facts and actions without inventing motives.", "Explain professional competence until the client withdraws the request, then document that the misunderstanding was corrected."], "answer": 2, "explain": "A stated preference is not evidence of incompetence or hostility. Respectful acknowledgment and coordinated options support dignity; staffing arrangements should not be promised beyond authority. Documentation records what was actually said and done.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-142", "chapter": 6, "mode": "scenarios", "topic": "Autonomy synthesis", "difficulty": 2, "prompt": "A client with a disability chooses food inconsistent with advice. A coworker proposes confiscating it because the client “cannot make good decisions.” No immediate emergency is described. Which response is best?", "choices": ["Let the coworker decide, because responsibility follows whoever first noticed the food.", "Do not infer incapacity from disability; clarify the choice, consult the plan, communicate concerns within scope, and seek appropriate review without assuming authority to confiscate.", "Assume refusal of advice proves capacity and omit reporting because any team involvement would be coercive.", "Treat disability as enough evidence to override the choice, provided the food is returned later."], "answer": 1, "explain": "Disability alone does not establish incapacity, and refusal alone does not establish capacity. Respectful clarification, the care plan, role-appropriate reporting and appropriate professional assessment address the concern without unsupported authority.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-143", "chapter": 6, "mode": "scenarios", "topic": "Wound-care synthesis", "difficulty": 2, "prompt": "A client declines wound care because it hurt previously. The HCA fears complications and wants to warn that sepsis is inevitable. Which response best combines communication and professional development?", "choices": ["Avoid discussing the refusal until the HCA has completed advanced wound-care education.", "Independently diagnose infection to establish urgency and perform the intervention despite the stated refusal.", "Use the strongest possible complication warning to secure agreement, then seek education afterward.", "Acknowledge pain, regulate personal fear, report the refusal and observations appropriately, document facts, and seek approved education or supervision about the knowledge gap."], "answer": 3, "explain": "Pain is a barrier to explore and report. Possible complications should not be presented as inevitable, and an HCA’s fear does not supply authority to diagnose or override. Learning and supervision can improve future communication within role.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-144", "chapter": 6, "mode": "scenarios", "topic": "Home safety synthesis", "difficulty": 2, "prompt": "During a home visit, an HCA keeps keys/phone accessible, uses a neutral tone, and safely withdraws under procedure when risk escalates. A student calls these unconscious defence mechanisms. Which correction and follow-up are strongest?", "choices": ["The neutral tone proves repression; keep practising it without reporting because emotional control resolves the safety concern.", "Every action that reduces anxiety is an unconscious mechanism, so no further safety analysis is needed.", "These may be conscious safety strategies; later examine warning signs, context and personal reactions, report the situation, and identify appropriate preparation or plan review.", "The withdrawal is displacement; the HCA should have remained until the task was finished to avoid reinforcing it."], "answer": 2, "explain": "A deliberate safety action is not automatically an unconscious defence mechanism. Necessary safety responses come first, followed by appropriate reporting, support and reflection. Emotional regulation does not replace safety procedures.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-145", "chapter": 6, "mode": "scenarios", "topic": "Advocacy synthesis", "difficulty": 2, "prompt": "An HCA observes a recurring change that a visiting clinician has not seen. An initial report receives little response. Which next step best supports advocacy within role?", "choices": ["Present specific observations, timing and relevant client statements, relate them to the plan, and use the appropriate escalation/documentation route to request review.", "Make a diagnosis before reporting again so the concern will sound credible.", "Change the care plan to demonstrate the importance of the observation.", "Conclude that the observation is irrelevant because the clinician did not witness it."], "answer": 0, "explain": "HCAs may contribute direct observations unavailable to visiting clinicians. Clear facts and appropriate escalation support advocacy without independent diagnosis or unilateral treatment changes.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-146", "chapter": 6, "mode": "scenarios", "topic": "Orders synthesis", "difficulty": 2, "prompt": "A client expresses a new treatment preference inconsistent with the current authorized order. The family asks the HCA to change it in the chart. What is the best response?", "choices": ["Ask the family to choose the order and record their decision as the HCA’s authorization.", "Revise the order because a reported preference automatically supplies authority to any worker who heard it.", "Ignore the statement because an existing order makes changing preferences irrelevant.", "Acknowledge and report the expressed preference for authorized review, explain the HCA cannot independently revise the order, and follow the applicable orders, plan and emergency procedures."], "answer": 3, "explain": "Preferences matter and should be communicated for appropriate review. The HCA cannot independently change the order. The scenario does not provide enough information or authority to decide treatment; applicable procedures remain important.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-147", "chapter": 6, "mode": "scenarios", "topic": "End-of-life synthesis", "difficulty": 2, "prompt": "An HCA finds an unresponsive client and is unsure whether the situation was expected. A coworker proposes pronouncing death and assuming an autopsy is mandatory. Which response is most appropriate?", "choices": ["Pronounce death first so the reporting process has a definitive starting point.", "Assume that uncertainty about the plan allows the HCA to choose any response that feels reasonable.", "Wait to determine whether an autopsy is required before using the emergency procedure.", "Follow applicable emergency/reporting procedures and authorized directions promptly, communicate observations, and avoid independent pronouncement or assumptions about universal autopsy requirements."], "answer": 3, "explain": "The brief emphasizes prompt, role-appropriate procedures and reporting. HCAs do not independently pronounce death, and unexpected circumstances do not establish a universal autopsy or coroner-attendance requirement.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-148", "chapter": 6, "mode": "scenarios", "topic": "Documentation synthesis", "difficulty": 2, "prompt": "The only known facts are that a client turned away and said, “Not now.” An HCA drafts, “Client was stubborn and wanted attention. I followed the plan, so I am legally protected.” Which revision is best supported?", "choices": ["Replace “stubborn” with “noncompliant,” retain the attention-seeking explanation, and add that the nurse was notified even if this is unknown.", "Record the observed turning away and quote, add relevant actions/notifications only if actually known or performed, and remove the motive labels and immunity claim.", "Keep the motive labels in quotation marks so they become objective facts.", "Delete the client’s words and record only the HCA’s confidence that the plan was followed."], "answer": 1, "explain": "Objective documentation separates observed actions and attributed words from inferred motives. Unknown actions must not be invented. Following the plan and documenting accurately do not guarantee immunity from liability.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-149", "chapter": 6, "mode": "scenarios", "topic": "Mature responses synthesis", "difficulty": 2, "prompt": "While supporting a grieving family, one worker knowingly postpones personal distress and later processes it; another insists the death did not occur; a third jokes insensitively to silence grief. Which interpretation is most accurate?", "choices": ["The first illustrates denial, the second suppression, and the third is appropriate if the worker intended to help.", "The first illustrates suppression, the second denial, and the third is not justified merely by calling humour mature.", "The first illustrates sublimation, the second projection, and the third proves emotional resilience.", "The first illustrates repression, the second anticipation, and the third is mature whenever it reduces discussion."], "answer": 1, "explain": "Temporary postponement of recognized distress is suppression; refusal to accept reality is denial. Mature humour acknowledges seriousness and fits the situation. Intention or a defence label does not justify silencing or belittling grief.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}, {"id": "ch6-150", "chapter": 6, "mode": "scenarios", "topic": "Reflection and reflexivity synthesis", "difficulty": 2, "prompt": "An HCA reflects, “I wanted to reassure the client. My authority may have made disagreement difficult. I assumed silence meant agreement.” Which follow-up most fully integrates reflective and reflexive practice?", "choices": ["Assume authority definitely caused the silence, then avoid any further clarification to prevent pressure.", "Focus only on the client’s communication style because professional authority cannot influence willingness to disagree.", "Treat the reassuring intention as proof of benefit and use silence as the outcome measure.", "Review the experience, examine how personal assumptions and position may have influenced it, invite preferences/check understanding in later encounters, and evaluate the responses."], "answer": 3, "explain": "Reflection reviews experience to guide later practice; reflexivity examines the worker’s assumptions, position and influence, including during interaction. Silence and good intentions do not establish agreement or benefit. The proposed influence should be explored rather than treated as proven.", "source": "Supplied Chapter 6, class slides and instructor source brief; see source notes for coverage limits.", "references": [{"href": "source-notes.md", "title": "Source notes and study guide"}], "written": false}]};
